import {articles as turkishArticles} from './blog.js';
const SITE='https://mythborn.co';
const publicPrefix=locale=>locale==='tr'?'':`/${locale==='el'?'gr':locale}`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const articles={

'eylul-2026-astroloji-ve-gezegen-gecisleri':{
 en:{title:'September 2026 Astrology and Planetary Transits: A Grounded Guide',dek:'A practical guide to the September sky: the Virgo New Moon, the Jupiter–Saturn square and the Libra equinox, without turning symbolism into certainty.',sections:[['The Virgo New Moon and mental clearing','The September New Moon in Virgo can be used as a symbolic prompt to review routines, work systems and the way attention is organised. It does not predict a fixed outcome.'],['The Jupiter–Saturn square and sustainable growth','The month’s Jupiter–Saturn tension invites a useful question: which form of growth can your time, skills and resources actually support?'],['The equinox and the Libra eclipse season','The equinox and the Libra themes of balance and relationship can support a review of agreements, boundaries and unfinished decisions.'],['Mercury in Libra and the end of the month','As Mercury moves through Libra, diplomacy and negotiation become useful reflection themes. Clear communication still depends on evidence, consent and context.']],faq:[['Which signs are most affected by the Virgo New Moon?','Symbolic astrology does not support a single guaranteed answer. Read the relevant house and lived context rather than assigning a fixed outcome by sign.'],['When is the September 2026 equinox?','The September equinox occurs around 22–23 September 2026, depending on time zone.']]},
 el:{title:'Αστρολογία Σεπτεμβρίου 2026 και Πλανητικές Διελεύσεις: Ένας Προσγειωμένος Οδηγός',dek:'Ένας πρακτικός οδηγός για τον ουρανό του Σεπτεμβρίου: τη Νέα Σελήνη στην Παρθένο, το τετράγωνο Δία–Κρόνου και την ισημερία στον Ζυγό, χωρίς βεβαιότητες.',sections:[['Η Νέα Σελήνη στην Παρθένο και η νοητική ανανέωση','Η Νέα Σελήνη στην Παρθένο μπορεί να λειτουργήσει ως συμβολική αφορμή για επανεξέταση ρουτινών, εργασίας και προσοχής. Δεν προβλέπει ένα σταθερό αποτέλεσμα.'],['Το τετράγωνο Δία–Κρόνου και η βιώσιμη ανάπτυξη','Η ένταση Δία–Κρόνου θέτει ένα χρήσιμο ερώτημα: ποια ανάπτυξη μπορούν πραγματικά να στηρίξουν ο χρόνος, οι δεξιότητες και οι πόροι σου;'],['Η ισημερία και ο Ζυγός','Η ισημερία και τα θέματα ισορροπίας του Ζυγού προσφέρουν χώρο για επανεξέταση συμφωνιών, ορίων και εκκρεμών αποφάσεων.'],['Ο Ερμής στον Ζυγό στο τέλος του μήνα','Με τον Ερμή στον Ζυγό, η διπλωματία και η διαπραγμάτευση γίνονται χρήσιμα θέματα αναστοχασμού. Η καθαρή επικοινωνία χρειάζεται πάντα στοιχεία, συναίνεση και πλαίσιο.']],faq:[['Ποια ζώδια επηρεάζονται περισσότερο από τη Νέα Σελήνη στην Παρθένο;','Η συμβολική αστρολογία δεν υποστηρίζει μία εγγυημένη απάντηση. Εξέτασε τον σχετικό οίκο και το πραγματικό πλαίσιο αντί για ένα σταθερό αποτέλεσμα ανά ζώδιο.'],['Πότε είναι η ισημερία του Σεπτεμβρίου 2026;','Η ισημερία του Σεπτεμβρίου συμβαίνει περίπου στις 22–23 Σεπτεμβρίου 2026, ανάλογα με τη ζώνη ώρας.']]},
 es:{title:'Astrología de septiembre de 2026 y tránsitos planetarios: una guía con los pies en la tierra',dek:'Una guía práctica del cielo de septiembre: la Luna nueva en Virgo, la cuadratura Júpiter–Saturno y el equinoccio en Libra, sin convertir el simbolismo en certeza.',sections:[['La Luna nueva en Virgo y la claridad mental','La Luna nueva de septiembre en Virgo puede servir como una invitación simbólica a revisar rutinas, sistemas de trabajo y atención. No predice un resultado fijo.'],['La cuadratura Júpiter–Saturno y el crecimiento sostenible','La tensión entre Júpiter y Saturno plantea una pregunta útil: ¿qué forma de crecimiento pueden sostener realmente tu tiempo, tus capacidades y tus recursos?'],['El equinoccio y los temas de Libra','El equinoccio y los temas de equilibrio y relación de Libra pueden ayudar a revisar acuerdos, límites y decisiones pendientes.'],['Mercurio en Libra al final del mes','Con Mercurio en Libra, la diplomacia y la negociación se vuelven temas útiles de reflexión. La comunicación clara sigue necesitando datos, consentimiento y contexto.']],faq:[['¿Qué signos reciben más influencia de la Luna nueva en Virgo?','La astrología simbólica no permite una respuesta única y garantizada. Conviene leer la casa relevante y el contexto real, no asignar un resultado fijo por signo.'],['¿Cuándo es el equinoccio de septiembre de 2026?','El equinoccio de septiembre ocurre aproximadamente el 22–23 de septiembre de 2026, según la zona horaria.']]},
 tr:{title:'Eylül 2026 Astroloji ve Gezegen Geçişleri Rehberi',dek:'Başak yeni ayı, Jüpiter-Satürn kare açısı ve Terazi ekinoksu ile eylül ayının göksel döngüleri ve burç analizleri.',sections:[['Başak Burcunda Yeni Ay ve Zihinsel Arınma (1-7 Eylül)','Eylül ayının ilk haftasında Başak burcunda gerçekleşecek yeni ay, günlük rutinlerimizde, iş süreçlerimizde ve zihinsel organizasyonumuzda düzen kurma ihtiyacımızı artırıyor.'],['Jüpiter - Satürn Kare Açısı ve Finansal Astroloji (8-15 Eylül)','Ayın ortasında kesinleşecek Jüpiter-Satürn sert açısı, büyüme arzumuz ile sorumluluklarımız arasında köprü kurmamızı gerektiriyor.'],['Ekinoksu ve Terazi Burcunda Güneş Tutulması (16-23 Eylül)','Sonbahar ekinoksu ile birlikte dengenin ve ilişkilerin temsilcisi Terazi burcuna geçiş yapıyoruz.'],['Merkür\'ün Terazi Burcuna Geçişi (24-30 Eylül)','Ayın son haftasında iletişim gezegeni Merkür\'ün Terazi burcuna geçişiyle diplomasi ve uzlaşma ön plana çıkıyor.']],faq:[['Başak yeni ayı hangi burçları etkiler?','Başak, İkizler, Yay ve Balık burçları bu yeni aydan doğrudan etki alabilir.'],['Eylül 2026’daki ekinoks ne zaman?','Sonbahar ekinoksu 22-23 Eylül tarihlerinde gerçekleşmektedir.']] }
},
'saturn-retrosu-2026':{
 en:{title:'Saturn Retrograde 2026: Boundaries, Responsibility and Rebuilding',dek:'A grounded guide to reviewing commitments, delayed work and sustainable structures without fear-based predictions.',sections:[['What Saturn retrograde represents','In symbolic astrology Saturn is linked with time, limits, responsibility and durable structure. A retrograde period is best used to review what is already carrying too much weight rather than inventing a new crisis.'],['How to read it personally','Look at the house Saturn is moving through, its aspects to natal Saturn, the Ascendant, Sun and Moon, and the real conditions of your life. A transit never replaces context.'],['A practical reflection','Choose one unfinished responsibility. Reduce it to a measurable weekly action, set a boundary around the resources it consumes and review the result after four weeks.']],faq:[['Is Saturn retrograde bad?','No. It is a symbolic review period, not a guarantee of loss or punishment.'],['Who may notice it most?','People with close contacts to natal Saturn, angles, Sun or Moon may experience the theme more clearly.']]},
 el:{title:'Ανάδρομος Κρόνος 2026: Όρια, Ευθύνη και Αναδόμηση',dek:'Ένας προσγειωμένος οδηγός για δεσμεύσεις, καθυστερήσεις και βιώσιμες δομές χωρίς φοβικές προβλέψεις.',sections:[['Τι συμβολίζει','Στη συμβολική αστρολογία ο Κρόνος συνδέεται με τον χρόνο, τα όρια, την ευθύνη και τις ανθεκτικές δομές. Η ανάδρομη φάση βοηθά να επανεξετάσουμε όσα ήδη μας βαραίνουν.'],['Προσωπική ανάγνωση','Εξετάζουμε τον οίκο διέλευσης, τις όψεις προς τον γενέθλιο Κρόνο, τον Ωροσκόπο, τον Ήλιο και τη Σελήνη, πάντα μαζί με τις πραγματικές συνθήκες ζωής.'],['Πρακτική άσκηση','Διάλεξε μία ανολοκλήρωτη ευθύνη, μετέτρεψέ την σε εβδομαδιαία πράξη και επανεκτίμησε το αποτέλεσμα μετά από τέσσερις εβδομάδες.']],faq:[['Είναι κακός ο ανάδρομος Κρόνος;','Όχι. Είναι περίοδος συμβολικής επανεξέτασης, όχι εγγύηση τιμωρίας.'],['Ποιοι τον αισθάνονται περισσότερο;','Όσοι έχουν στενές επαφές με τον γενέθλιο Κρόνο, τις γωνίες, τον Ήλιο ή τη Σελήνη.']]}
},
'12-agustos-2026-gunes-tutulmasi':{
 en:{title:'12 August 2026 Total Solar Eclipse: Astronomy and Symbolic Meaning',dek:'Separate verified eclipse facts from astrological symbolism and use the event as a careful reflection point.',sections:[['The astronomical event','The total solar eclipse of 12 August 2026 crosses parts of Greenland, Iceland and Spain, while a partial eclipse is visible across a wider region. Safe solar filters are required outside totality.'],['Astrological symbolism','Solar eclipses are commonly associated with visibility, direction and beginnings. Personal interpretation depends on degree, house placement and natal aspects.'],['A safer way to work with it','Instead of predicting a dramatic event, identify one area where your current direction needs a clearer intention, boundary or closing decision over the next six months.']],faq:[['Can I look at the eclipse directly?','Only during totality and only when local safety guidance confirms it; otherwise certified solar protection is required.'],['Does it affect everyone in the same way?','No. Symbolic interpretation varies by chart and lived context.']]},
 el:{title:'Ολική Έκλειψη Ηλίου 12 Αυγούστου 2026: Αστρονομία και Συμβολισμός',dek:'Διαχωρίζουμε τα επιβεβαιωμένα αστρονομικά δεδομένα από τον αστρολογικό συμβολισμό.',sections:[['Το αστρονομικό γεγονός','Η ολική έκλειψη της 12ης Αυγούστου 2026 διασχίζει περιοχές της Γροιλανδίας, της Ισλανδίας και της Ισπανίας. Εκτός ολικότητας απαιτούνται πιστοποιημένα φίλτρα.'],['Αστρολογικός συμβολισμός','Οι ηλιακές εκλείψεις συνδέονται συμβολικά με ορατότητα, κατεύθυνση και νέα ξεκινήματα. Η προσωπική ανάγνωση εξαρτάται από μοίρα, οίκο και όψεις.'],['Ασφαλής προσέγγιση','Αντί για δραματικές προβλέψεις, εντόπισε έναν τομέα όπου χρειάζεται καθαρότερη πρόθεση, όριο ή ολοκλήρωση.']],faq:[['Μπορώ να κοιτάξω την έκλειψη;','Μόνο σύμφωνα με τις επίσημες οδηγίες ασφαλείας και με κατάλληλη προστασία.'],['Επηρεάζει όλους το ίδιο;','Όχι. Η συμβολική ερμηνεία αλλάζει ανά χάρτη και πραγματικό πλαίσιο.']]}
},
'jupiter-aslanda-2026':{
 en:{title:'Jupiter in Leo 2026: Visibility, Creativity and Sustainable Growth',dek:'Explore confidence and creative expansion while keeping capacity, resources and accountability in view.',sections:[['Core theme','Jupiter expands and Leo expresses. Together they can highlight leadership, performance, visibility and the wish to create something memorable.'],['The shadow side','Overpromising, spending for appearance and confusing attention with durable success are the main risks.'],['Personal chart focus','Read the house containing Leo and contacts to the natal Sun, Venus and Jupiter. Growth becomes useful when it can be supported by time, skill and resources.']],faq:[['Does Jupiter always bring luck?','Jupiter amplifies opportunity and excess; management matters.'],['Is this only relevant to Leo signs?','No. Every chart contains Leo and therefore a life area activated by the transit.']]},
 el:{title:'Ο Δίας στον Λέοντα 2026: Ορατότητα, Δημιουργία και Βιώσιμη Ανάπτυξη',dek:'Εξερεύνησε την αυτοπεποίθηση και τη δημιουργική επέκταση χωρίς να αγνοείς πόρους και ευθύνη.',sections:[['Κεντρικό θέμα','Ο Δίας διευρύνει και ο Λέων εκφράζει. Ο συνδυασμός τονίζει ηγεσία, σκηνή, δημιουργικότητα και ορατότητα.'],['Σκιώδης πλευρά','Υπερβολικές υποσχέσεις, δαπάνες για εντύπωση και σύγχυση προσοχής με σταθερή επιτυχία είναι βασικοί κίνδυνοι.'],['Προσωπικός χάρτης','Δες τον οίκο του Λέοντα και τις επαφές με Ήλιο, Αφροδίτη και Δία. Η ανάπτυξη χρειάζεται χρόνο, δεξιότητα και πόρους.']],faq:[['Φέρνει πάντα τύχη ο Δίας;','Μεγεθύνει τόσο τις ευκαιρίες όσο και την υπερβολή.'],['Αφορά μόνο Λέοντες;','Όχι. Κάθε χάρτης έχει έναν τομέα που κυβερνά ο Λέων.']]}
},
'uranus-ikizlerde-teknoloji-yapay-zeka':{
 en:{title:'Uranus in Gemini: AI, Communication and New Mental Habits',dek:'Use the transit as a framework for examining information, attention and digital behaviour rather than as a technology prophecy.',sections:[['Why it matters','Uranus is associated with disruption and Gemini with language, networks, learning and transport. This makes the transit a popular symbol for fast changes in media and AI.'],['Personal level','Review how you consume information, protect attention, verify sources and build an online identity.'],['Critical boundary','Astrology does not scientifically predict technological events. It can still offer a reflective narrative for your response to change.']],faq:[['Does this predict a technology collapse?','No. Such a claim would be unsupported.'],['What should I examine in a chart?','The Gemini house and Mercury–Uranus contacts are common starting points.']]},
 el:{title:'Ο Ουρανός στους Διδύμους: Τεχνητή Νοημοσύνη και Νέες Νοητικές Συνήθειες',dek:'Ένα πλαίσιο για πληροφορία, προσοχή και ψηφιακή συμπεριφορά — όχι τεχνολογική προφητεία.',sections:[['Γιατί συζητείται','Ο Ουρανός συνδέεται με ανατροπή και οι Δίδυμοι με γλώσσα, δίκτυα και μάθηση. Έτσι η διέλευση συνδέεται συμβολικά με AI και μέσα.'],['Προσωπικό επίπεδο','Εξέτασε πώς καταναλώνεις πληροφορία, προστατεύεις την προσοχή και επαληθεύεις πηγές.'],['Κριτικό όριο','Η αστρολογία δεν προβλέπει επιστημονικά τεχνολογικά γεγονότα. Μπορεί όμως να λειτουργήσει ως αφήγηση αυτοπαρατήρησης.']],faq:[['Προβλέπει τεχνολογική κατάρρευση;','Όχι. Μια τέτοια βεβαιότητα δεν στηρίζεται σε δεδομένα.'],['Τι εξετάζεται στον χάρτη;','Ο οίκος των Διδύμων και οι επαφές Ερμή–Ουρανού.']]}
},
'sinastri-nedir':{
 en:{title:'What Is Synastry? Why Compatibility Is More Than Sun Signs',dek:'Understand how Moon, Mercury, Venus, Mars and Saturn contacts describe different relationship functions.',sections:[['The method','Synastry compares the planetary positions of two natal charts. It is more useful as a map of themes than as one compatibility percentage.'],['Key indicators','The Moon describes emotional safety, Mercury communication, Venus affection, Mars attraction and conflict rhythm, and Saturn commitment and boundaries.'],['Healthy use','A difficult aspect does not mean a bad relationship, and an easy aspect does not guarantee one. Behaviour and values remain decisive.']],faq:[['Is birth time required?','It is essential for angles and houses; many planetary comparisons can still be made without it.'],['Is a compatibility score certain?','No. It is a symbolic summary, not a verdict.']]},
 el:{title:'Τι Είναι η Συναστρία; Γιατί η Συμβατότητα Δεν Είναι Μόνο τα Ζώδια Ήλιου',dek:'Πώς οι επαφές Σελήνης, Ερμή, Αφροδίτης, Άρη και Κρόνου περιγράφουν διαφορετικές λειτουργίες σχέσης.',sections:[['Η μέθοδος','Η συναστρία συγκρίνει τις πλανητικές θέσεις δύο γενέθλιων χαρτών. Είναι χάρτης θεμάτων, όχι ένας τελικός αριθμός.'],['Κύριοι δείκτες','Η Σελήνη αφορά ασφάλεια, ο Ερμής επικοινωνία, η Αφροδίτη τρυφερότητα, ο Άρης έλξη και σύγκρουση, ο Κρόνος δέσμευση και όρια.'],['Υγιής χρήση','Μια δύσκολη όψη δεν σημαίνει κακή σχέση και μια εύκολη όψη δεν την εγγυάται. Συμπεριφορά και αξίες παραμένουν καθοριστικές.']],faq:[['Χρειάζεται ώρα γέννησης;','Ναι για γωνίες και οίκους· πολλές πλανητικές συγκρίσεις γίνονται και χωρίς αυτή.'],['Είναι βέβαιο το ποσοστό συμβατότητας;','Όχι. Είναι συμβολική σύνοψη.']]}
},
'saturn-donusu-rehberi':{
 en:{title:'What Is the Saturn Return? A Practical Guide to Ages 27–30',dek:'Frame the Saturn return as a developmental checkpoint involving responsibility, work, relationships and long-term direction.',sections:[['What it is','Saturn returns to its natal position roughly every 29 years. The first return overlaps with major adult transitions.'],['Why it feels intense','Career, commitment, money and identity often require firmer choices during this stage of life.'],['A useful exercise','Write three structures you want to maintain and three burdens you need to release. Evaluate each decision by time, values and resources.']],faq:[['Does everyone experience it at the same age?','Exact timing depends on the natal Saturn degree.'],['Is there a second return?','Yes, usually around ages 58–60.']]},
 el:{title:'Τι Είναι η Επιστροφή του Κρόνου; Οδηγός για τις Ηλικίες 27–30',dek:'Ένα αναπτυξιακό σημείο ελέγχου για ευθύνη, εργασία, σχέσεις και μακροπρόθεσμη κατεύθυνση.',sections:[['Τι είναι','Ο Κρόνος επιστρέφει στη γενέθλια θέση περίπου κάθε 29 χρόνια. Η πρώτη επιστροφή συμπίπτει με σημαντικές μεταβάσεις ενηλικίωσης.'],['Γιατί είναι έντονη','Καριέρα, δέσμευση, χρήματα και ταυτότητα ζητούν πιο σταθερές επιλογές.'],['Χρήσιμη άσκηση','Γράψε τρεις δομές που θέλεις να κρατήσεις και τρία βάρη που χρειάζεται να αφήσεις. Αξιολόγησε χρόνο, αξίες και πόρους.']],faq:[['Συμβαίνει σε όλους στην ίδια ηλικία;','Η ακριβής στιγμή εξαρτάται από τη γενέθλια μοίρα του Κρόνου.'],['Υπάρχει δεύτερη επιστροφή;','Ναι, περίπου στα 58–60.']]}
},
'astrokartografi-nedir':{
 en:{title:'What Is Astrocartography? Place, Travel and Planetary Lines',dek:'Read planetary lines as a reflective geography tool, not as a guarantee that a move will succeed.',sections:[['Basic principle','Astrocartography maps where planets were rising, setting, culminating or anti-culminating at birth.'],['How lines are read','Sun lines are associated with visibility, Venus with connection, Mars with action, Saturn with responsibility and Jupiter with expansion.'],['Decision boundary','A move must still be evaluated through visas, work, income, safety, climate and community. Astrology cannot replace these facts.']],faq:[['Must I live directly on a line?','No. Distance and the relocated chart also matter.'],['Is birth time important?','Yes. Accurate angular lines depend on it.']]},
 el:{title:'Τι Είναι η Αστροχαρτογραφία; Τόπος, Ταξίδι και Πλανητικές Γραμμές',dek:'Οι πλανητικές γραμμές ως εργαλείο γεωγραφικού στοχασμού, όχι εγγύηση επιτυχίας μετακόμισης.',sections:[['Βασική αρχή','Η αστροχαρτογραφία χαρτογραφεί πού οι πλανήτες ανέτειλαν, έδυαν ή μεσουρανούσαν τη στιγμή της γέννησης.'],['Ανάγνωση γραμμών','Ο Ήλιος συνδέεται με ορατότητα, η Αφροδίτη με σχέσεις, ο Άρης με δράση, ο Κρόνος με ευθύνη και ο Δίας με επέκταση.'],['Όριο απόφασης','Μετακόμιση αξιολογείται με βίζα, εργασία, εισόδημα, ασφάλεια, κλίμα και κοινότητα. Η αστρολογία δεν αντικαθιστά αυτά τα δεδομένα.']],faq:[['Πρέπει να ζω πάνω στη γραμμή;','Όχι. Μετρούν η απόσταση και ο χάρτης μετεγκατάστασης.'],['Είναι σημαντική η ώρα γέννησης;','Ναι, οι γωνιακές γραμμές απαιτούν ακρίβεια.']]}
},
'travma-bilincli-astroloji':{
 en:{title:'Trauma-Informed Astrology: Reading a Chart Without Fear',dek:'Use astrological language with safety, transparency, choice and boundaries — never as diagnosis or therapy.',sections:[['Core principle','A trauma-informed approach prioritises safety, trust, collaboration and choice.'],['Language to avoid','Statements such as “your chart is broken” or “this aspect proves trauma” are misleading and potentially harmful.'],['A safer question','Ask what a symbol brings up for the person and allow them to define relevance, pace and boundaries.']],faq:[['Is astrology therapy?','No. It does not replace qualified mental-health care.'],['What if a reading feels overwhelming?','Pause, return to a sense of safety and seek professional support when needed.']]},
 el:{title:'Τραυματο-Ενημερωμένη Αστρολογία: Ανάγνωση Χωρίς Φόβο',dek:'Ασφάλεια, διαφάνεια, επιλογή και όρια — ποτέ διάγνωση ή θεραπεία.',sections:[['Βασική αρχή','Η τραυματο-ενημερωμένη προσέγγιση δίνει προτεραιότητα στην ασφάλεια, την εμπιστοσύνη, τη συνεργασία και την επιλογή.'],['Γλώσσα που αποφεύγεται','Φράσεις όπως «ο χάρτης σου είναι χαλασμένος» ή «η όψη αποδεικνύει τραύμα» είναι παραπλανητικές και επιβλαβείς.'],['Ασφαλέστερη ερώτηση','Ρώτησε τι ενεργοποιεί το σύμβολο και άφησε το άτομο να ορίσει συνάφεια, ρυθμό και όρια.']],faq:[['Είναι η αστρολογία θεραπεία;','Όχι. Δεν αντικαθιστά ειδικό ψυχικής υγείας.'],['Τι κάνω αν νιώσω υπερφόρτωση;','Σταμάτησε, επέστρεψε σε αίσθηση ασφάλειας και ζήτησε υποστήριξη όταν χρειάζεται.']]}
},
'yapay-zeka-tarot-etik':{
 en:{title:'AI Tarot Interpretation: Possibilities, Limits and Ethics',dek:'Keep the line between useful personalisation and false certainty clear in AI-assisted symbolic readings.',sections:[['What AI can do well','It can organise symbols, offer multiple perspectives and help a person frame a question.'],['Where limits are required','Health, law, finance, death and guaranteed future claims require strict boundaries.'],['The Mythborn standard','Readings remain symbolic, choice-oriented and transparent about uncertainty.']],faq:[['Can AI know the future?','No. It generates interpretations, not verified future knowledge.'],['Should I make major decisions from a reading?','No. Use real evidence and qualified advice.']]},
 el:{title:'Ερμηνεία Ταρώ με AI: Δυνατότητες, Όρια και Ηθική',dek:'Καθαρό όριο ανάμεσα στη χρήσιμη προσωποποίηση και την ψευδή βεβαιότητα.',sections:[['Τι κάνει καλά η AI','Μπορεί να οργανώσει σύμβολα, να προσφέρει οπτικές και να βοηθήσει στη διατύπωση ερώτησης.'],['Πού χρειάζονται όρια','Υγεία, νόμος, οικονομικά, θάνατος και βέβαιες προβλέψεις απαιτούν αυστηρούς περιορισμούς.'],['Το πρότυπο Mythborn','Οι αναγνώσεις παραμένουν συμβολικές, προσανατολισμένες στην επιλογή και διαφανείς ως προς την αβεβαιότητα.']],faq:[['Γνωρίζει η AI το μέλλον;','Όχι. Παράγει ερμηνείες, όχι επαληθευμένη γνώση μέλλοντος.'],['Να πάρω μεγάλη απόφαση από ανάγνωση;','Όχι. Χρησιμοποίησε πραγματικά στοιχεία και ειδικούς.']]}
},
'tarot-ve-astrolojiyi-birlikte-okumak':{
 en:{title:'How to Read Tarot and Astrology Together',dek:'Combine transits and cards as different symbolic layers without using one to “prove” the other.',sections:[['Different functions','Astrology offers timing and structural context; Tarot can focus attention on a question, choice or emotional pattern.'],['A clean method','Define the transit first, ask one open question, draw a limited spread and compare themes rather than forcing agreement.'],['Avoiding confirmation bias','Record the reading before events unfold and review later. Do not reinterpret every card to fit a preferred conclusion.']],faq:[['Which comes first?','Start with the concrete question and context; then use the symbolic tool that fits.'],['Should both systems give the same answer?','No. Difference can be more informative than forced agreement.']]},
 el:{title:'Πώς Διαβάζουμε Μαζί Ταρώ και Αστρολογία',dek:'Δύο διαφορετικά συμβολικά επίπεδα χωρίς να χρησιμοποιούμε το ένα ως «απόδειξη» του άλλου.',sections:[['Διαφορετικές λειτουργίες','Η αστρολογία δίνει χρονισμό και δομή· το Ταρώ εστιάζει σε ερώτηση, επιλογή ή συναισθηματικό μοτίβο.'],['Καθαρή μέθοδος','Όρισε πρώτα τη διέλευση, κάνε μία ανοιχτή ερώτηση, χρησιμοποίησε μικρό άνοιγμα και σύγκρινε θέματα.'],['Αποφυγή επιβεβαιωτικής προκατάληψης','Κατέγραψε την ανάγνωση πριν εξελιχθούν τα γεγονότα και επανεξέτασέ την αργότερα.']],faq:[['Ποιο σύστημα έρχεται πρώτο;','Ξεκίνα από την πραγματική ερώτηση και το πλαίσιο.'],['Πρέπει να δίνουν την ίδια απάντηση;','Όχι. Η διαφορά μπορεί να είναι πιο χρήσιμη από την εξαναγκασμένη συμφωνία.']]}
}
,'dogum-saatini-bilmiyorum':{
 en:{title:'I Don’t Know My Birth Time: What Can Still Be Calculated?',dek:'A practical guide to the chart layers that remain reliable when birth time is unknown and the ones that should not be guessed.',sections:[['Why birth time matters','Birth time determines time-sensitive points such as the Ascendant, houses and MC. When it is unknown, those layers should not be guessed and presented as certain.'],['What can still be read?','The Sun, most planetary sign positions and some aspects can be calculated from the date. The Moon needs care when it is close to a sign boundary because time can change the result.'],['A safer method','Use the unknown-time option, read only reliable date-based results and recalculate when an official record provides the time.']],faq:[['Can I find my Ascendant without birth time?','Not reliably. The Ascendant can change roughly every two hours, so guessing creates false precision.'],['Is a birth chart useful without time?','Yes. Date-based planetary positions and some aspects remain useful, but houses, MC and Ascendant should be withheld.'],['What should I do if I find my time later?','Recalculate the chart with the verified time and place instead of mixing the two versions.']]},
 el:{title:'Δεν Γνωρίζω την Ώρα Γέννησής μου: Τι Μπορεί ακόμη να Υπολογιστεί;',dek:'Ένας πρακτικός οδηγός για τα αξιόπιστα επίπεδα του χάρτη όταν η ώρα γέννησης είναι άγνωστη και για όσα δεν πρέπει να μαντεύονται.',sections:[['Γιατί έχει σημασία η ώρα','Η ώρα καθορίζει τον Ωροσκόπο, τους οίκους και το Μεσουράνημα. Όταν είναι άγνωστη, αυτά τα επίπεδα δεν πρέπει να παρουσιάζονται με ψεύτικη ακρίβεια.'],['Τι μπορεί να διαβαστεί;','Ο Ήλιος, οι περισσότερες πλανητικές θέσεις στα ζώδια και ορισμένες όψεις μπορούν να υπολογιστούν από την ημερομηνία. Η Σελήνη χρειάζεται προσοχή όταν βρίσκεται κοντά σε όριο ζωδίου.'],['Ασφαλέστερη μέθοδος','Χρησιμοποίησε την επιλογή άγνωστης ώρας, διάβασε μόνο αξιόπιστα στοιχεία βάσει ημερομηνίας και επανυπολόγισε όταν βρεθεί επίσημη ώρα.']],faq:[['Μπορώ να βρω τον Ωροσκόπο χωρίς ώρα;','Όχι με αξιοπιστία. Ο Ωροσκόπος μπορεί να αλλάζει περίπου κάθε δύο ώρες και η εικασία δημιουργεί ψευδή ακρίβεια.'],['Έχει χρησιμότητα ο χάρτης χωρίς ώρα;','Ναι. Οι πλανητικές θέσεις βάσει ημερομηνίας και ορισμένες όψεις παραμένουν χρήσιμες, αλλά όχι οι οίκοι, το Μεσουράνημα και ο Ωροσκόπος.'],['Τι κάνω αν βρω αργότερα την ώρα;','Υπολόγισε ξανά τον χάρτη με την επιβεβαιωμένη ώρα και τον τόπο γέννησης.']]}
},
'sinastri-nasil-okunur':{
 en:{title:'How to Read Synastry: Emotion, Communication, Attraction and Commitment',dek:'A guide to reading Moon, Mercury, Venus, Mars and Saturn contacts in context instead of reducing two charts to one compatibility score.',sections:[['Check data quality first','Use accurate birth dates, places and, when possible, times. If time is unknown, the context of angles and houses is limited and that limitation should be visible.'],['Separate relationship functions','The Moon can frame emotional safety, Mercury communication, Venus affection and values, Mars attraction and conflict rhythm, and Saturn responsibility and boundaries.'],['Why a score is not enough','One aspect does not determine relationship quality. Easy aspects are not guarantees and difficult aspects are not failure; behaviour, consent, values and real conditions remain decisive.']],faq:[['What should I look at first in synastry?','Check data quality, then examine Moon, Mercury, Venus, Mars and Saturn contacts within the whole chart.'],['Is birth time required for synastry?','Not always for planetary comparisons, but it matters for the Ascendant, houses and personal context.'],['Does a difficult aspect mean a bad relationship?','No. It may describe tension or a growth task, not a verdict about the relationship.']]},
 el:{title:'Πώς Διαβάζεται η Συναστρία: Συναίσθημα, Επικοινωνία, Έλξη και Δέσμευση',dek:'Οδηγός για την ανάγνωση επαφών Σελήνης, Ερμή, Αφροδίτης, Άρη και Κρόνου μέσα στο πλαίσιο, όχι ως έναν τελικό βαθμό συμβατότητας.',sections:[['Έλεγξε πρώτα τα δεδομένα','Χρησιμοποίησε σωστές ημερομηνίες, τόπους και, όταν είναι δυνατό, ώρες γέννησης. Αν η ώρα είναι άγνωστη, το πλαίσιο γωνιών και οίκων είναι περιορισμένο.'],['Ξεχώρισε τις λειτουργίες της σχέσης','Η Σελήνη αφορά συναισθηματική ασφάλεια, ο Ερμής επικοινωνία, η Αφροδίτη τρυφερότητα και αξίες, ο Άρης έλξη και σύγκρουση, ενώ ο Κρόνος ευθύνη και όρια.'],['Γιατί δεν αρκεί ένας βαθμός','Μία όψη δεν καθορίζει την ποιότητα μιας σχέσης. Οι εύκολες όψεις δεν εγγυώνται και οι δύσκολες δεν καταδικάζουν· συμπεριφορά, συναίνεση, αξίες και πραγματικές συνθήκες παραμένουν καθοριστικές.']],faq:[['Τι εξετάζουμε πρώτα στη συναστρία;','Την ποιότητα των δεδομένων και έπειτα τις επαφές Σελήνης, Ερμή, Αφροδίτης, Άρη και Κρόνου μέσα σε ολόκληρο τον χάρτη.'],['Χρειάζεται ώρα γέννησης;','Όχι πάντα για πλανητικές συγκρίσεις, αλλά είναι σημαντική για Ωροσκόπο, οίκους και προσωπικό πλαίσιο.'],['Σημαίνει μια δύσκολη όψη κακή σχέση;','Όχι. Μπορεί να δείχνει ένταση ή πεδίο ανάπτυξης, όχι τελική κρίση.']]}
},
'uc-kart-tarot-nasil-okunur':{
 en:{title:'How to Read a 3-Card Tarot Spread in Context',dek:'Use the question, positions, repeating symbols and choice space to connect three cards without treating one spread as a fixed prophecy.',sections:[['Narrow the question','Instead of asking “What will happen?”, ask what dynamic you need to notice or which next step you need to clarify.'],['Read the cards as a sentence','Do not treat each card as a separate prediction. Read positions, shared colours, repeating numbers and tension between the cards together. Past-present-future is only one possible structure.'],['Keep a boundary around certainty','Tarot does not provide verified knowledge of the future. A reading can help you notice options and emotions, but it does not replace a decision or evidence.']],faq:[['How should I choose the positions?','Past-present-future is one option; situation-choice-next step or feeling-obstacle-resource may fit a specific question better.'],['Do reversed cards have to be used?','No. Reversals are optional. Choose a method before the reading and apply it consistently.'],['Should I ask the same question repeatedly?','Usually not. Repeating a spread can increase anxiety and confirmation seeking instead of clarity.']]},
 el:{title:'Πώς Διαβάζεται ένα Άνοιγμα Ταρώ 3 Καρτών μέσα στο Πλαίσιο',dek:'Σύνδεσε τρεις κάρτες με βάση την ερώτηση, τις θέσεις, τα επαναλαμβανόμενα σύμβολα και τον χώρο επιλογής χωρίς να τις θεωρείς βέβαιη προφητεία.',sections:[['Περιορίσε την ερώτηση','Αντί για «τι θα συμβεί;», ρώτησε ποια δυναμική χρειάζεται να προσέξεις ή ποιο επόμενο βήμα χρειάζεται να ξεκαθαρίσεις.'],['Διάβασε τις κάρτες σαν πρόταση','Μην αντιμετωπίζεις κάθε κάρτα ως ξεχωριστή πρόβλεψη. Δες μαζί τις θέσεις, τα κοινά χρώματα, τους αριθμούς και την ένταση μεταξύ τους.'],['Κράτησε όριο στη βεβαιότητα','Το Ταρώ δεν προσφέρει επαληθευμένη γνώση του μέλλοντος. Μπορεί να αναδείξει επιλογές και συναισθήματα, αλλά δεν αντικαθιστά απόφαση ή στοιχεία.']],faq:[['Πώς επιλέγω τις θέσεις;','Παρελθόν-παρόν-μέλλον είναι μία επιλογή· κατάσταση-επιλογή-επόμενο βήμα ή συναίσθημα-εμπόδιο-πόρος μπορεί να ταιριάζει καλύτερα.'],['Είναι απαραίτητες οι ανεστραμμένες κάρτες;','Όχι. Είναι προαιρετικές. Διάλεξε μέθοδο πριν από την ανάγνωση και ακολούθησέ την με συνέπεια.'],['Να επαναλαμβάνω την ίδια ερώτηση;','Συνήθως όχι. Η επανάληψη μπορεί να αυξήσει το άγχος και την αναζήτηση επιβεβαίωσης.']]}
}
};

const globalTrendArticles={
'venus-retrosu-2026-akrep-terazi':{
 en:{title:'Venus Retrograde 2026: Dates, Scorpio–Libra Themes and What to Review',dek:'A detailed guide to the 3 October–14 November 2026 Venus retrograde through relationships, values, money and natal-chart context.',sections:[['When is Venus retrograde in 2026?','Venus stations retrograde on 3 October 2026 in Scorpio, returns to Libra later in October and turns direct on 14 November. Retrograde motion is an apparent change in motion as seen from Earth, not a planet literally moving backwards.'],['Why Scorpio and Libra matter','In symbolic astrology Venus is associated with affection, values, aesthetics and resources. Scorpio can frame trust, intimacy and shared resources; Libra can frame reciprocity, fairness and agreements.'],['How to personalise the transit','Look first at the houses containing Scorpio and Libra, then at close contacts to natal Venus, Moon, Mars and the relationship axis. Sun-sign lists alone are too broad for a personal reading.'],['A practical way to use the period','Review subscriptions, spending patterns, relationship boundaries and unresolved conversations. Do not postpone important real-life decisions merely because Venus is retrograde; use evidence and context.']],faq:[['When is Venus retrograde in 2026?','From 3 October to 14 November 2026.'],['Does Venus retrograde bring an ex back?','It can coincide with renewed reflection on past relationships, but it cannot guarantee that a specific person will return.'],['Is it bad to start a relationship during Venus retrograde?','No. There is no universal prohibition; real compatibility, consent and circumstances matter more.'],['Which signs are most affected?','Charts with strong Scorpio or Libra placements may notice the themes more clearly, but houses and natal aspects matter.']]},
 es:{title:'Venus retrógrado 2026: fechas, temas de Escorpio–Libra y qué revisar',dek:'Guía detallada del Venus retrógrado del 3 de octubre al 14 de noviembre de 2026 en relaciones, valores, dinero y carta natal.',sections:[['¿Cuándo es Venus retrógrado en 2026?','Venus inicia su retrogradación el 3 de octubre de 2026 en Escorpio, vuelve a Libra más adelante en octubre y se pone directo el 14 de noviembre. El movimiento retrógrado es aparente desde la Tierra.'],['Por qué importan Escorpio y Libra','En astrología simbólica Venus se asocia con afecto, valores, estética y recursos. Escorpio puede hablar de confianza, intimidad y recursos compartidos; Libra de reciprocidad, equilibrio y acuerdos.'],['Cómo personalizar el tránsito','Observa las casas donde caen Escorpio y Libra y después los contactos con Venus, Luna, Marte y el eje relacional natal. Una lista por signo solar es demasiado general.'],['Cómo usar este periodo','Revisa suscripciones, hábitos de gasto, límites en relaciones y conversaciones pendientes. No retrases decisiones importantes solo por la retrogradación; usa datos y contexto.']],faq:[['¿Cuándo es Venus retrógrado en 2026?','Del 3 de octubre al 14 de noviembre de 2026.'],['¿Vuelve un ex durante Venus retrógrado?','Puede reactivar temas del pasado, pero no garantiza que una persona concreta vuelva.'],['¿Es malo empezar una relación?','No. No existe una prohibición universal; importan la compatibilidad real, el consentimiento y las circunstancias.'],['¿Qué signos lo notan más?','Las cartas con énfasis en Escorpio o Libra pueden sentir el tema con más claridad, pero importan casas y aspectos.']]},
 el:{title:'Ανάδρομη Αφροδίτη 2026: Ημερομηνίες, Σκορπιός–Ζυγός και Τι να Επανεξετάσεις',dek:'Αναλυτικός οδηγός για την ανάδρομη Αφροδίτη 3 Οκτωβρίου–14 Νοεμβρίου 2026 σε σχέσεις, αξίες, χρήματα και γενέθλιο χάρτη.',sections:[['Πότε είναι ανάδρομη η Αφροδίτη το 2026;','Η Αφροδίτη γυρίζει ανάδρομη στις 3 Οκτωβρίου 2026 στον Σκορπιό, επιστρέφει αργότερα στον Ζυγό και ορθοδρομεί στις 14 Νοεμβρίου. Η ανάδρομη κίνηση είναι φαινόμενο παρατήρησης από τη Γη.'],['Γιατί έχουν σημασία Σκορπιός και Ζυγός','Στη συμβολική αστρολογία η Αφροδίτη συνδέεται με σχέσεις, αξίες, αισθητική και πόρους. Ο Σκορπιός τονίζει εμπιστοσύνη και κοινά οικονομικά, ενώ ο Ζυγός αμοιβαιότητα και συμφωνίες.'],['Πώς γίνεται προσωπική ανάγνωση','Δες τους οίκους του Σκορπιού και του Ζυγού και τις επαφές με γενέθλια Αφροδίτη, Σελήνη, Άρη και άξονα σχέσεων.'],['Πρακτική χρήση','Επανεξέτασε έξοδα, συνδρομές, όρια και εκκρεμείς συζητήσεις. Μην αναβάλλεις σημαντικές αποφάσεις μόνο λόγω ανάδρομης κίνησης.']],faq:[['Πότε είναι ανάδρομη η Αφροδίτη;','3 Οκτωβρίου έως 14 Νοεμβρίου 2026.'],['Επιστρέφει πρώην σύντροφος;','Μπορεί να επανέλθουν παλιά θέματα, αλλά δεν υπάρχει εγγύηση επιστροφής συγκεκριμένου ατόμου.'],['Είναι κακό να ξεκινήσει σχέση;','Όχι. Οι πραγματικές συνθήκες, η συναίνεση και η συμβατότητα έχουν μεγαλύτερη σημασία.'],['Ποια ζώδια επηρεάζονται περισσότερο;','Ισχυρές θέσεις σε Σκορπιό ή Ζυγό μπορεί να κάνουν το θέμα πιο ορατό, αλλά χρειάζονται οίκοι και όψεις.']]}
},
'merkur-retrosu-2026-ekim-kasim-akrep':{
 en:{title:'Mercury Retrograde 2026: 24 October–13 November in Scorpio',dek:'Dates, shadow period, communication themes and a practical natal-chart guide to the final Mercury retrograde of 2026.',sections:[['Key dates','Mercury turns retrograde on 24 October 2026 in Scorpio and direct on 13 November. The pre-shadow begins in early October and the post-shadow ends near the end of November.'],['Why Scorpio changes the tone','Mercury symbolises communication, planning and information. Scorpio adds themes of privacy, trust, shared resources and hidden assumptions.'],['A practical checklist','Back up important files, re-read contracts and payment terms, verify recipients and attachments, and replace assumptions with explicit questions. These are useful habits regardless of astrology.'],['How to personalise it','Locate Scorpio in the natal chart and check close contacts to Mercury, Mars, Moon and the Ascendant. A Sun-sign-only reading is too broad.']],faq:[['When is Mercury retrograde in late 2026?','24 October to 13 November 2026.'],['What should you avoid?','There is no universal ban list. Increase checks around documents, payments, backups and communication.'],['Which signs are affected?','Scorpio-heavy charts may notice the themes more clearly, but houses and natal aspects matter.'],['Can I sign a contract?','Yes if necessary. Read terms carefully and obtain appropriate professional advice when needed.']]},
 es:{title:'Mercurio retrógrado 2026: 24 de octubre–13 de noviembre en Escorpio',dek:'Fechas, periodo de sombra, comunicación y guía práctica de carta natal para el último Mercurio retrógrado de 2026.',sections:[['Fechas clave','Mercurio inicia la retrogradación el 24 de octubre de 2026 en Escorpio y se pone directo el 13 de noviembre. La sombra empieza a comienzos de octubre y termina hacia finales de noviembre.'],['Por qué Escorpio cambia el tono','Mercurio simboliza comunicación, planificación e información. Escorpio añade privacidad, confianza, recursos compartidos y supuestos ocultos.'],['Lista práctica','Haz copias de seguridad, revisa contratos y pagos, confirma destinatarios y archivos adjuntos y sustituye suposiciones por preguntas claras.'],['Cómo personalizarlo','Localiza Escorpio en tu carta y revisa contactos con Mercurio, Marte, Luna y Ascendente. Leer solo el signo solar es demasiado general.']],faq:[['¿Cuándo es Mercurio retrógrado?','Del 24 de octubre al 13 de noviembre de 2026.'],['¿Qué no se debe hacer?','No hay una lista universal de prohibiciones. Conviene aumentar controles en documentos, pagos, copias y comunicación.'],['¿Qué signos lo notan más?','Cartas con fuerte Escorpio pueden notarlo más, pero importan casas y aspectos.'],['¿Se puede firmar un contrato?','Sí, si es necesario. Lee bien las condiciones y busca asesoramiento profesional cuando corresponda.']]},
 el:{title:'Ανάδρομος Ερμής 2026: 24 Οκτωβρίου–13 Νοεμβρίου στον Σκορπιό',dek:'Ημερομηνίες, σκιά, επικοινωνία και πρακτικός οδηγός γενέθλιου χάρτη για τον τελευταίο ανάδρομο Ερμή του 2026.',sections:[['Κύριες ημερομηνίες','Ο Ερμής γυρίζει ανάδρομος στις 24 Οκτωβρίου 2026 στον Σκορπιό και ορθοδρομεί στις 13 Νοεμβρίου. Η περίοδος σκιάς εκτείνεται περίπου από τις αρχές Οκτωβρίου έως τα τέλη Νοεμβρίου.'],['Γιατί αλλάζει ο τόνος στον Σκορπιό','Ο Ερμής συμβολίζει επικοινωνία, σχέδιο και πληροφορία. Ο Σκορπιός προσθέτει ιδιωτικότητα, εμπιστοσύνη και κοινά οικονομικά.'],['Πρακτική λίστα','Κάνε αντίγραφα ασφαλείας, έλεγξε συμβόλαια και πληρωμές, επιβεβαίωσε παραλήπτες και συνημμένα και κάνε σαφείς ερωτήσεις.'],['Προσωπική ανάγνωση','Δες τον οίκο του Σκορπιού και επαφές με Ερμή, Άρη, Σελήνη και Ωροσκόπο.']],faq:[['Πότε είναι ανάδρομος ο Ερμής;','24 Οκτωβρίου έως 13 Νοεμβρίου 2026.'],['Τι πρέπει να αποφεύγεται;','Δεν υπάρχει καθολική λίστα απαγορεύσεων· αύξησε τους ελέγχους σε έγγραφα, πληρωμές και επικοινωνία.'],['Ποιοι το νιώθουν περισσότερο;','Χάρτες με έμφαση στον Σκορπιό μπορεί να το αισθανθούν πιο καθαρά, αλλά χρειάζονται οίκοι και όψεις.'],['Μπορώ να υπογράψω συμβόλαιο;','Ναι, όταν χρειάζεται. Διάβασε προσεκτικά και ζήτησε κατάλληλη επαγγελματική συμβουλή.']]}
},
'mars-retrosu-2027-basak-aslan':{
 en:{title:'Mars Retrograde 2027: Virgo–Leo Dates, Energy and Strategy',dek:'A detailed guide to the 10 January–1 April 2027 Mars retrograde through motivation, conflict, work systems and natal-chart context.',sections:[['When is Mars retrograde in 2027?','Mars stations retrograde on 10 January 2027 in Virgo and turns direct on 1 April in Leo, moving back across themes associated with method, performance and personal drive.'],['Virgo to Leo','Virgo can symbolise systems, work and refinement; Leo creativity, visibility and self-expression. Retrograde symbolism can be used to review how effort is spent.'],['What to review','Instead of pushing harder at the same problem, examine process, energy leaks, recurring conflict and unsustainable routines.'],['Personal chart focus','Read the Virgo and Leo houses and contacts to natal Mars, Sun and angles. Personal interpretation depends on degree and context.']],faq:[['When is Mars retrograde in 2027?','10 January to 1 April 2027.'],['Which signs does it cross?','It begins in Virgo and moves back into Leo.'],['Should I avoid starting a job?','No universal ban applies. Evaluate goals, resources, timing and actual opportunity.'],['Who may notice it most?','Charts with strong Virgo or Leo placements may notice the themes more clearly.']]},
 es:{title:'Marte retrógrado 2027: fechas en Virgo–Leo, energía y estrategia',dek:'Guía detallada del Marte retrógrado del 10 de enero al 1 de abril de 2027 sobre motivación, conflicto, sistemas de trabajo y carta natal.',sections:[['¿Cuándo es Marte retrógrado en 2027?','Marte inicia su retrogradación el 10 de enero de 2027 en Virgo y se pone directo el 1 de abril en Leo.'],['De Virgo a Leo','Virgo puede simbolizar método, trabajo y mejora; Leo creatividad, visibilidad y expresión personal. El periodo puede servir para revisar cómo gastas energía.'],['Qué revisar','En vez de empujar más fuerte el mismo problema, revisa procesos, fugas de energía, conflictos repetidos y rutinas insostenibles.'],['Carta natal','Observa las casas de Virgo y Leo y los contactos con Marte, Sol y ángulos natales.']],faq:[['¿Cuándo es Marte retrógrado?','Del 10 de enero al 1 de abril de 2027.'],['¿Por qué signos pasa?','Comienza en Virgo y retrocede hacia Leo.'],['¿Debo evitar empezar un trabajo?','No existe una prohibición universal. Evalúa objetivos, recursos y oportunidad real.'],['¿Quién puede notarlo más?','Cartas con fuerte Virgo o Leo pueden sentir el tema con mayor claridad.']]},
 el:{title:'Ανάδρομος Άρης 2027: Παρθένος–Λέων, Ενέργεια και Στρατηγική',dek:'Αναλυτικός οδηγός για τον ανάδρομο Άρη 10 Ιανουαρίου–1 Απριλίου 2027 σε κίνητρο, συγκρούσεις, εργασία και γενέθλιο χάρτη.',sections:[['Πότε είναι ανάδρομος ο Άρης;','Ο Άρης γυρίζει ανάδρομος στις 10 Ιανουαρίου 2027 στην Παρθένο και ορθοδρομεί την 1η Απριλίου στον Λέοντα.'],['Από Παρθένο σε Λέοντα','Η Παρθένος συμβολίζει σύστημα και βελτίωση, ο Λέων δημιουργία, ορατότητα και έκφραση. Η περίοδος μπορεί να λειτουργήσει ως έλεγχος της χρήσης ενέργειας.'],['Τι να επανεξετάσεις','Αντί να πιέζεις περισσότερο, έλεγξε διαδικασία, διαρροές ενέργειας, επαναλαμβανόμενες συγκρούσεις και μη βιώσιμες ρουτίνες.'],['Γενέθλιος χάρτης','Δες τους οίκους Παρθένου και Λέοντα και επαφές με Άρη, Ήλιο και γωνίες.']],faq:[['Πότε είναι ανάδρομος ο Άρης;','10 Ιανουαρίου έως 1 Απριλίου 2027.'],['Σε ποια ζώδια κινείται;','Ξεκινά στην Παρθένο και επιστρέφει στον Λέοντα.'],['Να αποφεύγω νέα δουλειά;','Όχι. Αξιολόγησε στόχους, πόρους και πραγματικές συνθήκες.'],['Ποιοι το νιώθουν περισσότερο;','Χάρτες με έντονη Παρθένο ή Λέοντα μπορεί να το παρατηρήσουν πιο καθαρά.']]}
},
'2027-astroloji-takvimi-retrolar-tutulmalar':{
 en:{title:'2027 Astrology Calendar: Retrogrades, Eclipses and Major Sky Dates',dek:'A single reference page for the major 2027 retrogrades, solar and lunar eclipses, and the key dates worth tracking throughout the year.',sections:[['The year at a glance','2027 opens with Mars retrograde, includes three Mercury retrograde periods and features two notable solar eclipses. Use the calendar as a planning reference, not as a good/bad-day rulebook.'],['Mercury and Mars retrogrades','Mars is retrograde from 10 January to 1 April. Mercury has three retrograde periods in February–March, June–July and October.'],['Solar eclipses','An annular solar eclipse occurs on 6 February 2027 and a total solar eclipse on 2 August 2027. Visibility varies by location and safe solar-viewing rules apply.'],['Lunar eclipses','The year also includes lunar eclipse events in February and August. Exact local visibility depends on geography and time zone.'],['How to use the calendar','Save the dates, then map each event to the relevant natal house and degree. Real-world decisions should still be based on evidence, resources and qualified advice.']],faq:[['How many Mercury retrogrades are there in 2027?','Three.'],['Is Mars retrograde in 2027?','Yes, from 10 January to 1 April.'],['When is the total solar eclipse?','2 August 2027.'],['How many solar eclipses are there in 2027?','Two: an annular eclipse in February and a total eclipse in August.']]},
 es:{title:'Calendario astrológico 2027: retrógrados, eclipses y fechas clave',dek:'Página de referencia para los grandes retrógrados de 2027, eclipses solares y lunares y fechas importantes del año.',sections:[['El año de un vistazo','2027 comienza con Marte retrógrado, incluye tres periodos de Mercurio retrógrado y dos eclipses solares destacados. Úsalo como referencia, no como lista de días buenos o malos.'],['Mercurio y Marte retrógrados','Marte está retrógrado del 10 de enero al 1 de abril. Mercurio tendrá tres periodos: febrero–marzo, junio–julio y octubre.'],['Eclipses solares','Habrá un eclipse anular el 6 de febrero y un eclipse total el 2 de agosto de 2027. La visibilidad depende del lugar.'],['Eclipses lunares','También habrá eclipses lunares en febrero y agosto. La visibilidad exacta depende de geografía y zona horaria.'],['Cómo usar el calendario','Guarda las fechas y después observa qué casa y grado natal activa cada evento. Las decisiones reales deben basarse en datos y contexto.']],faq:[['¿Cuántos Mercurio retrógrados hay en 2027?','Tres.'],['¿Hay Marte retrógrado?','Sí, del 10 de enero al 1 de abril.'],['¿Cuándo es el eclipse total de Sol?','2 de agosto de 2027.'],['¿Cuántos eclipses solares hay?','Dos: uno anular en febrero y uno total en agosto.']]},
 el:{title:'Αστρολογικό Ημερολόγιο 2027: Ανάδρομοι, Εκλείψεις και Κύριες Ημερομηνίες',dek:'Μία σελίδα αναφοράς για τους σημαντικούς ανάδρομους του 2027, τις ηλιακές και σεληνιακές εκλείψεις και τις βασικές ημερομηνίες.',sections:[['Η χρονιά συνοπτικά','Το 2027 ξεκινά με ανάδρομο Άρη, περιλαμβάνει τρεις περιόδους ανάδρομου Ερμή και δύο σημαντικές ηλιακές εκλείψεις.'],['Ερμής και Άρης','Ο Άρης είναι ανάδρομος 10 Ιανουαρίου–1 Απριλίου. Ο Ερμής έχει τρεις περιόδους: Φεβρουάριο–Μάρτιο, Ιούνιο–Ιούλιο και Οκτώβριο.'],['Ηλιακές εκλείψεις','Δακτυλιοειδής έκλειψη στις 6 Φεβρουαρίου και ολική στις 2 Αυγούστου 2027. Η ορατότητα εξαρτάται από την τοποθεσία.'],['Σεληνιακές εκλείψεις','Υπάρχουν επίσης σεληνιακές εκλείψεις τον Φεβρουάριο και τον Αύγουστο.'],['Πώς να χρησιμοποιήσεις το ημερολόγιο','Κράτησε τις ημερομηνίες και έπειτα σύνδεσέ τες με οίκο και μοίρα στον γενέθλιο χάρτη.']],faq:[['Πόσες φορές είναι ανάδρομος ο Ερμής;','Τρεις.'],['Είναι ανάδρομος ο Άρης;','Ναι, 10 Ιανουαρίου–1 Απριλίου.'],['Πότε είναι η ολική έκλειψη Ηλίου;','2 Αυγούστου 2027.'],['Πόσες ηλιακές εκλείψεις υπάρχουν;','Δύο: μία δακτυλιοειδής και μία ολική.']]}
},
'2-agustos-2027-gunes-tutulmasi-aslan':{
 en:{title:'2 August 2027 Total Solar Eclipse: Visibility, 9° Leo and Rising-Sign Themes',dek:'A long-form guide to the 2 August 2027 total solar eclipse: visibility, safe observing, the Leo degree and practical interpretation by rising sign.',sections:[['Why this eclipse stands out','The 2 August 2027 eclipse is a total solar eclipse with a long path of totality crossing southern Europe, North Africa and the Middle East. Turkey lies outside the totality path but can see a partial eclipse.'],['Safe observing','Never look directly at the Sun during partial phases. Use ISO-compliant eclipse glasses or an appropriate indirect projection method.'],['The astrology degree','In tropical astrology the eclipse occurs near 9°55′ Leo. Natal placements close to this degree in fixed signs are commonly examined for a more specific symbolic reading.'],['Leo symbolism','Leo is associated with visibility, creativity, confidence and personal expression. The useful question is not “what will happen?” but “where do I need more authentic visibility?”'],['Rising-sign approach','Read the eclipse through the natal house containing 9° Leo. Aries rising may emphasise creativity, Taurus home, Gemini communication, Cancer resources, Leo identity, Virgo retreat, Libra networks, Scorpio career, Sagittarius worldview, Capricorn shared resources, Aquarius partnership and Pisces routines.'],['A practical exercise','Write down where you seek applause, where you avoid visibility and one creative or personal project you can support consistently over six months.']],faq:[['Will the eclipse be visible from Turkey?','Yes, as a partial solar eclipse; exact coverage depends on location.'],['What degree is the eclipse?','Around 9°55′ Leo in tropical astrology.'],['Which signs are most relevant?','Leo, Aquarius, Taurus and Scorpio placements near the eclipse degree are commonly examined.'],['Can I look at it without protection?','No during partial phases. Certified solar protection is required.'],['Does it guarantee a major event?','No. Astrological interpretation is symbolic, not a guaranteed prediction.']]},
 es:{title:'Eclipse solar total del 2 de agosto de 2027: visibilidad, 9° de Leo y Ascendente',dek:'Guía extensa del eclipse total del 2 de agosto de 2027: visibilidad, observación segura, grado de Leo e interpretación por Ascendente.',sections:[['Por qué destaca','El eclipse del 2 de agosto de 2027 será total, con una larga franja de totalidad por el sur de Europa, norte de África y Oriente Medio. Turquía quedará fuera de la totalidad, pero verá un eclipse parcial.'],['Observación segura','Nunca mires directamente al Sol durante las fases parciales. Usa gafas de eclipse certificadas o proyección indirecta segura.'],['El grado astrológico','En astrología tropical ocurre cerca de 9°55′ de Leo. Se suelen revisar posiciones natales cercanas en signos fijos.'],['Simbolismo de Leo','Leo se asocia con visibilidad, creatividad, confianza y expresión personal. La pregunta útil es dónde necesitas mostrarte de forma más auténtica.'],['Lectura por Ascendente','Se interpreta según la casa natal que contiene 9° de Leo. Aries puede enfatizar creatividad; Tauro hogar; Géminis comunicación; Cáncer recursos; Leo identidad; Virgo retiro; Libra redes; Escorpio carrera; Sagitario visión; Capricornio recursos compartidos; Acuario pareja; Piscis rutinas.'],['Ejercicio práctico','Anota dónde buscas aprobación, dónde evitas visibilidad y qué proyecto creativo puedes sostener durante seis meses.']],faq:[['¿Se verá desde Turquía?','Sí, como eclipse parcial; la cobertura exacta depende de la ciudad.'],['¿En qué grado ocurre?','Alrededor de 9°55′ de Leo.'],['¿Qué signos son más relevantes?','Leo, Acuario, Tauro y Escorpio cerca del grado del eclipse.'],['¿Se puede mirar sin protección?','No durante las fases parciales.'],['¿Garantiza un gran acontecimiento?','No. La interpretación astrológica es simbólica.']]},
 el:{title:'Ολική Έκλειψη Ηλίου 2 Αυγούστου 2027: Ορατότητα, 9° Λέοντα και Ωροσκόπος',dek:'Αναλυτικός οδηγός για την ολική έκλειψη 2 Αυγούστου 2027: ορατότητα, ασφαλής παρατήρηση, μοίρα Λέοντα και ανάγνωση ανά Ωροσκόπο.',sections:[['Γιατί ξεχωρίζει','Η έκλειψη της 2ας Αυγούστου 2027 είναι ολική, με ζώνη ολικότητας σε νότια Ευρώπη, Βόρεια Αφρική και Μέση Ανατολή. Η Τουρκία θα δει μερική έκλειψη.'],['Ασφαλής παρατήρηση','Μην κοιτάς ποτέ τον Ήλιο απευθείας στις μερικές φάσεις. Χρησιμοποίησε πιστοποιημένα γυαλιά έκλειψης ή ασφαλή έμμεση προβολή.'],['Η αστρολογική μοίρα','Στην τροπική αστρολογία η έκλειψη γίνεται περίπου στις 9°55′ Λέοντα. Εξετάζονται γενέθλιες θέσεις κοντά σε αυτή τη μοίρα στα σταθερά ζώδια.'],['Συμβολισμός Λέοντα','Ο Λέων συνδέεται με ορατότητα, δημιουργικότητα, αυτοπεποίθηση και προσωπική έκφραση.'],['Ανάγνωση ανά Ωροσκόπο','Η ερμηνεία βασίζεται στον οίκο όπου πέφτουν οι 9° Λέοντα. Οι θεματικές αλλάζουν από δημιουργία και σπίτι έως καριέρα, σχέσεις και ρουτίνες.'],['Πρακτική άσκηση','Σημείωσε πού ζητάς επιβεβαίωση, πού αποφεύγεις ορατότητα και ποιο δημιουργικό σχέδιο μπορείς να στηρίξεις για έξι μήνες.']],faq:[['Θα είναι ορατή από την Τουρκία;','Ναι, ως μερική έκλειψη.'],['Σε ποια μοίρα γίνεται;','Περίπου στις 9°55′ Λέοντα.'],['Ποια ζώδια είναι πιο σχετικά;','Λέων, Υδροχόος, Ταύρος και Σκορπιός κοντά στη μοίρα της έκλειψης.'],['Μπορώ να κοιτάξω χωρίς προστασία;','Όχι στις μερικές φάσεις.'],['Εγγυάται κάποιο μεγάλο γεγονός;','Όχι. Η αστρολογική ερμηνεία είναι συμβολική.']]}
},
'venus-retrosu-2026-yukselene-gore':{
 en:{title:'Venus Retrograde 2026 by Rising Sign: Love, Money and Relationship Themes',dek:'A house-by-house guide to the 3 October–14 November 2026 Venus retrograde for all 12 rising signs.',sections:[['Why rising sign matters','The Ascendant determines the house framework, so it gives more context than a Sun-sign-only reading.'],['The two-stage transit','Venus begins retrograde in Scorpio and later returns to Libra, shifting the symbolic emphasis from depth and trust to reciprocity and balance.'],['Aries to Cancer rising','Aries: shared resources then partnerships. Taurus: partnerships then daily routines. Gemini: work and habits then creativity. Cancer: romance and creativity then home and family.'],['Leo to Scorpio rising','Leo: home then communication. Virgo: communication then money and values. Libra: money then identity. Scorpio: identity then retreat and closure.'],['Sagittarius to Pisces rising','Sagittarius: retreat then networks. Capricorn: networks then career. Aquarius: career then worldview and travel. Pisces: worldview then shared resources and intimacy.'],['Five useful relationship questions','What am I tired of giving? What do I need but avoid saying? Is time and money sharing fair? Am I confusing attraction with trust? Would I choose this relationship again today?']],faq:[['When is Venus retrograde?','3 October to 14 November 2026.'],['Why read by rising sign?','Because rising sign determines the houses where Scorpio and Libra fall.'],['Does it guarantee an ex returns?','No. It may highlight past patterns, not guarantee a specific return.'],['Is cosmetic work forbidden?','No universal astrological ban applies; safety and qualified professional advice matter more.'],['Does Venus retrograde cause breakups?','No. Relationship outcomes depend on real dynamics and decisions.']]},
 es:{title:'Venus retrógrado 2026 por Ascendente: amor, dinero y relaciones',dek:'Guía casa por casa del Venus retrógrado del 3 de octubre al 14 de noviembre de 2026 para los 12 Ascendentes.',sections:[['Por qué importa el Ascendente','El Ascendente determina las casas y aporta más contexto que leer solo el signo solar.'],['Dos etapas','Venus empieza retrógrado en Escorpio y vuelve a Libra, pasando simbólicamente de profundidad y confianza a reciprocidad y equilibrio.'],['Ascendentes Aries a Cáncer','Aries: recursos compartidos y pareja. Tauro: pareja y rutinas. Géminis: trabajo y creatividad. Cáncer: romance y hogar.'],['Ascendentes Leo a Escorpio','Leo: hogar y comunicación. Virgo: comunicación y dinero. Libra: dinero e identidad. Escorpio: identidad y cierre.'],['Ascendentes Sagitario a Piscis','Sagitario: retiro y redes. Capricornio: redes y carrera. Acuario: carrera y visión del mundo. Piscis: visión y recursos compartidos.'],['Cinco preguntas útiles','¿Qué estoy cansado de dar? ¿Qué necesito y no digo? ¿Compartimos tiempo y dinero con justicia? ¿Confundo atracción con confianza? ¿Elegiría hoy esta relación?']],faq:[['¿Cuándo es Venus retrógrado?','3 de octubre a 14 de noviembre de 2026.'],['¿Por qué leer el Ascendente?','Porque determina las casas donde caen Escorpio y Libra.'],['¿Garantiza que vuelva un ex?','No. Puede reactivar patrones del pasado, no garantizar una vuelta concreta.'],['¿Está prohibida la estética?','No. Importan más seguridad y consejo profesional.'],['¿Causa rupturas?','No. Los resultados dependen de la dinámica real de la relación.']]},
 el:{title:'Ανάδρομη Αφροδίτη 2026 ανά Ωροσκόπο: Αγάπη, Χρήματα και Σχέσεις',dek:'Οδηγός ανά οίκο για την ανάδρομη Αφροδίτη 3 Οκτωβρίου–14 Νοεμβρίου 2026 και τους 12 Ωροσκόπους.',sections:[['Γιατί έχει σημασία ο Ωροσκόπος','Ο Ωροσκόπος καθορίζει τους οίκους και δίνει περισσότερο πλαίσιο από τον Ήλιο μόνο.'],['Δύο στάδια','Η Αφροδίτη ξεκινά ανάδρομη στον Σκορπιό και επιστρέφει στον Ζυγό, μετακινώντας τον συμβολισμό από βάθος και εμπιστοσύνη σε αμοιβαιότητα και ισορροπία.'],['Ωροσκόποι Κριός έως Καρκίνος','Κριός: κοινά οικονομικά και σχέσεις. Ταύρος: σχέσεις και καθημερινότητα. Δίδυμοι: εργασία και δημιουργία. Καρκίνος: έρωτας και σπίτι.'],['Λέων έως Σκορπιός','Λέων: σπίτι και επικοινωνία. Παρθένος: επικοινωνία και χρήματα. Ζυγός: χρήματα και ταυτότητα. Σκορπιός: ταυτότητα και κλείσιμο.'],['Τοξότης έως Ιχθύες','Τοξότης: εσωστρέφεια και δίκτυα. Αιγόκερως: δίκτυα και καριέρα. Υδροχόος: καριέρα και κοσμοθεωρία. Ιχθύες: κοσμοθεωρία και κοινά οικονομικά.'],['Πέντε ερωτήσεις σχέσης','Τι κουράστηκα να δίνω; Τι χρειάζομαι αλλά δεν λέω; Είναι δίκαιη η μοιρασιά χρόνου και χρημάτων; Μπερδεύω έλξη με εμπιστοσύνη; Θα επέλεγα ξανά αυτή τη σχέση σήμερα;']],faq:[['Πότε είναι ανάδρομη η Αφροδίτη;','3 Οκτωβρίου έως 14 Νοεμβρίου 2026.'],['Γιατί ανά Ωροσκόπο;','Επειδή ο Ωροσκόπος καθορίζει τους οίκους Σκορπιού και Ζυγού.'],['Εγγυάται επιστροφή πρώην;','Όχι. Μπορεί να επαναφέρει παλιά μοτίβα, όχι συγκεκριμένο άτομο.'],['Απαγορεύονται αισθητικές πράξεις;','Όχι. Προέχουν ασφάλεια και ειδικός.'],['Προκαλεί χωρισμούς;','Όχι. Οι πραγματικές δυναμικές της σχέσης είναι καθοριστικές.']]}
}
};
Object.assign(articles,globalTrendArticles);

const labels={tr:{journal:'GÖKYÜZÜ GÜNDEMİ · DERİN REHBERLER',hero:'Bugünün merakını, yarının arşivine dönüştür.',lead:'Güncel gökyüzü olayları, ilişki astrolojisi, etik ve kişisel farkındalık üzerine özgün uzun form içerikler.',read:'Yazıyı oku →',back:'← Tüm yazılar',faq:'SIK SORULANLAR',faqLead:'Konuyla ilgili kısa yanıtlar.',note:'Eğlence, eğitim ve kişisel farkındalık amaçlıdır. Astroloji ve Tarot bilimsel tanı veya garantili öngörü yöntemleri değildir.'},en:{journal:'SKY JOURNAL · IN-DEPTH GUIDES',hero:'Turn today’s curiosity into tomorrow’s archive.',lead:'Original long-form guides on current celestial events, relationship astrology, ethics and self-reflection.',read:'Read article →',back:'← All articles',faq:'FREQUENTLY ASKED QUESTIONS',faqLead:'Clear answers to common questions.',note:'For entertainment, education and personal reflection. Astrology and Tarot are not scientific diagnosis or guaranteed prediction methods.'},el:{journal:'ΟΥΡΑΝΙΟ ΠΕΡΙΟΔΙΚΟ · ΑΝΑΛΥΤΙΚΟΙ ΟΔΗΓΟΙ',hero:'Μετέτρεψε τη σημερινή περιέργεια στο αυριανό αρχείο.',lead:'Πρωτότυποι οδηγοί για ουράνια γεγονότα, σχέσεις, ηθική και αυτογνωσία.',read:'Διάβασε το άρθρο →',back:'← Όλα τα άρθρα',faq:'ΣΥΧΝΕΣ ΕΡΩΤΗΣΕΙΣ',faqLead:'Σαφείς απαντήσεις σε συχνές ερωτήσεις.',note:'Για ψυχαγωγία, εκπαίδευση και προσωπικό στοχασμό. Η αστρολογία και το Ταρώ δεν είναι επιστημονική διάγνωση ή εγγυημένη πρόβλεψη.'},es:{journal:'DIARIO DEL CIELO · GUÍAS EN PROFUNDIDAD',hero:'Convierte la curiosidad de hoy en el archivo de mañana.',lead:'Guías originales sobre fenómenos celestes, astrología relacional, ética y reflexión personal.',read:'Leer artículo →',back:'← Todos los artículos',faq:'PREGUNTAS FRECUENTES',faqLead:'Respuestas claras a preguntas habituales.',note:'Para entretenimiento, educación y reflexión personal. La astrología y el Tarot no son diagnósticos científicos ni métodos de predicción garantizada.'}};
function shell(locale,title,description,body,path){const l=labels[locale],prefix=publicPrefix(locale),canonical=`${SITE}${prefix}${path}`;return`<!doctype html><html lang="${locale}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)} — Mythborn</title><meta name="description" content="${esc(description)}"><link rel="canonical" href="${canonical}"><link rel="alternate" hreflang="tr" href="${SITE}${path}"><link rel="alternate" hreflang="en" href="${SITE}${publicPrefix('en')}${path}"><link rel="alternate" hreflang="el" href="${SITE}${publicPrefix('el')}${path}"><link rel="alternate" hreflang="es" href="${SITE}${publicPrefix('es')}${path}"><link rel="alternate" hreflang="x-default" href="${SITE}${path}"><link rel="stylesheet" href="/app.css"><link rel="stylesheet" href="/oracle.css"><link rel="stylesheet" href="/final.css"><script type="application/ld+json">${JSON.stringify({'@context':'https://schema.org','@type':path==='/blog'?'CollectionPage':'Article',name:title,description,url:canonical,inLanguage:locale})}</script><meta property="og:type" content="article"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:url" content="${canonical}"></head><body><div class="shell"><header class="topbar"><a class="brand" href="${prefix}"><img src="/images/mythborn-emblem.png" alt=""><span>MYTHBORN</span></a><nav class="nav"><a href="${prefix}/gunluk-kart">${locale==='tr'?'Günlük Kart':locale==='en'?'Daily Card':locale==='es'?'Carta diaria':'Ημερήσια Κάρτα'}</a><a href="${prefix}/astroloji">${locale==='tr'?'Astroloji':locale==='en'?'Astrology':locale==='es'?'Astrología':'Αστρολογία'}</a><a href="${prefix}/sinastri">${locale==='tr'?'Sinastri':locale==='en'?'Synastry':locale==='es'?'Sinastría':'Συναστρία'}</a><a href="${prefix}/blog">${locale==='tr'?'Blog':locale==='en'?'Journal':locale==='es'?'Diario':'Περιοδικό'}</a><a href="${prefix}/hesabim">${locale==='tr'?'Hesabım':locale==='en'?'My Account':locale==='es'?'Mi cuenta':'Ο Λογαριασμός μου'}</a></nav></header><main>${body}</main></div><nav class="language-switcher" aria-label="Language"><a href="${path}">TR</a><a href="${publicPrefix('en')}${path}"${locale==='en'?' aria-current="page"':''}>EN</a><a href="${publicPrefix('el')}${path}"${locale==='el'?' aria-current="page"':''}>GR</a><a href="${publicPrefix('es')}${path}"${locale==='es'?' aria-current="page"':''}>ES</a></nav><style>.blog-hero{padding:64px 0 34px}.blog-hero h1{max-width:800px;font-family:Georgia,serif;font-size:clamp(42px,6vw,72px);font-weight:400;line-height:.98}.blog-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;padding-bottom:70px}.blog-card{padding:22px;border:1px solid rgba(255,255,255,.13);border-radius:20px;background:rgba(255,255,255,.035)}.blog-card h2{font-family:Georgia,serif;font-size:clamp(25px,2.5vw,36px);font-weight:400;line-height:1.04}.blog-card p,.article-lead,.article-body p{color:#aaa2b0;line-height:1.75}.article{width:min(860px,100%);margin:auto;padding:64px 0}.article h1{font-family:Georgia,serif;font-size:clamp(42px,6vw,72px);font-weight:400;line-height:.98}.article-meta{margin:16px 0 0;color:#efad7d;font:800 10px/1.4 system-ui;letter-spacing:.14em;text-transform:uppercase}.article-body section{padding:28px 0;border-top:1px solid rgba(255,255,255,.12)}.article-body h2{font-family:Georgia,serif;font-size:clamp(28px,3.5vw,42px);font-weight:400}.article-faq details{padding:16px 0;border-top:1px solid rgba(255,255,255,.1)}.article-note{margin-top:34px;padding:18px;border:1px solid rgba(232,200,131,.25);border-radius:16px}.language-switcher{position:fixed;right:14px;bottom:18px;z-index:90;display:flex;gap:4px;padding:5px;border:1px solid rgba(255,255,255,.13);border-radius:999px;background:rgba(9,7,13,.94)}.language-switcher a{display:grid;place-items:center;min-width:34px;min-height:34px;border-radius:999px;font:800 10px system-ui}.language-switcher a[aria-current=page]{background:#f4eee5;color:#09070c}@media(max-width:900px){.blog-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:620px){.blog-grid{grid-template-columns:1fr}.blog-hero,.article{padding-top:42px}}</style><script src="/final.js" defer></script><script src="/menu.js" defer></script></body></html>`}
for(const [slug,content] of Object.entries(spanishBlog)){if(articles[slug]&&!articles[slug].es)articles[slug].es=content;}
for(const article of turkishArticles){if(!articles[article.slug])articles[article.slug]={};articles[article.slug].tr={title:article.title,dek:article.dek,sections:article.sections,faq:article.faq};}
export const localizedBlogSlugs=Object.keys(articles);
export const localizedBlogSearchItems=locale=>Object.entries(articles).map(([slug,translations])=>{const item=translations[locale]||translations.en;return{title:item.title,description:item.dek,category:'journal',path:`/blog/${slug}`}});
export function localizedBlogPage(locale,path){const l=labels[locale];if(path==='/blog'){const cards=Object.entries(articles).map(([slug,data])=>{const a=data[locale]||data.en||data.tr;return`<article class="blog-card"><small>${locale==='tr'?'MYTHBORN REHBERİ':locale==='en'?'MYTHBORN GUIDE':locale==='es'?'GUÍA MYTHBORN':'ΟΔΗΓΟΣ MYTHBORN'}</small><h2>${esc(a.title)}</h2><p>${esc(a.dek)}</p><a href="${publicPrefix(locale)}/blog/${slug}">${l.read}</a></article>`}).join('');return shell(locale,locale==='tr'?'Astroloji, Tarot ve Gökyüzü Blogu':locale==='en'?'Astrology, Tarot and Sky Journal':locale==='es'?'Diario de astrología, Tarot y cielo':'Περιοδικό Αστρολογίας, Ταρώ και Ουρανού',l.lead,`<section class="blog-hero"><p class="eyebrow">${l.journal}</p><h1>${l.hero}</h1><p class="lead left-lead">${l.lead}</p></section><section class="blog-grid">${cards}</section>`,'/blog')}
 const slug=path.replace('/blog/',''),translations=articles[slug],data=translations?.[locale]||translations?.en||translations?.tr;if(!data)return null;const date=blogDates[path];const graph=JSON.stringify({'@context':'https://schema.org','@graph':[{'@type':'Article',headline:data.title,description:data.dek,inLanguage:locale,url:`${SITE}${publicPrefix(locale)}${path}`,publisher:{'@type':'Organization',name:'Mythborn',url:SITE},author:{'@type':'Organization',name:'Mythborn Editorial Desk',url:SITE},...(date?{datePublished:date,dateModified:date}: {})},{'@type':'FAQPage',mainEntity:data.faq.map(([q,a])=>({'@type':'Question',name:q,acceptedAnswer:{'@type':'Answer',text:a}}))}]});const body=`<article class="article"><a href="${publicPrefix(locale)}/blog">${l.back}</a><h1>${esc(data.title)}</h1>${date?`<p class="article-meta">${locale==='tr'?'MYTHBORN EDITORIAL DESK':locale==='en'?'MYTHBORN EDITORIAL DESK':locale==='es'?'EQUIPO EDITORIAL MYTHBORN':'ΣΥΝΤΑΚΤΙΚΗ ΟΜΑΔΑ MYTHBORN'} · ${date}</p>`:''}<p class="article-lead">${esc(data.dek)}</p><div class="article-body">${data.sections.map(([h,p])=>`<section><h2>${esc(h)}</h2><p>${esc(p)}</p></section>`).join('')}<section class="article-faq"><p class="eyebrow">${l.faq}</p><h2>${l.faqLead}</h2>${data.faq.map(([q,a])=>`<details><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join('')}</section><p class="article-note">${l.note}</p></div><script type="application/ld+json">${graph}</script></article>`;return shell(locale,data.title,data.dek,body,path)}
